#include <iostream>
#include <cmath>
#include <vector>

using namespace std;

const int MAXN = 32000;
vector<int> primes;
bool is_composite[MAXN] = {false};

void sieve() {
    for (int i = 2; i < MAXN; ++i) {
        if (!is_composite[i]) {
            primes.push_back(i);
        }
        for (int p : primes) {
            if (p * i >= MAXN) break;
            is_composite[p * i] = true;
            if (i % p == 0) break;
        }
    }
}

bool is_prime(int x) {
    if (x < 2) return false;
    if (x < MAXN) return !is_composite[x];
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0) return false;
    }
    return true;
}

bool is_perfect_square(int x) {
    int r = sqrt(x);
    return r * r == x;
}

int main() {
    sieve();
    int x;
    cin >> x;
    int ans = 0;
    while (!is_perfect_square(x)) {
        if (is_prime(x)) {
            x -= 1;
        } else {
            for (int p : primes) {
                if (x % p == 0) {
                    x /= p;
                    break;
                }
            }
        }
        ++ans;
    }
    cout << ans << endl;
    return 0;
}
